"""Evaluator-authored literal portable schema0 seeds; no candidate imports.

Generated once with the exact public legacy schema. Immutable bytes, rather than
host SQLite version-dependent regeneration, are bound into each browser history.
Source generation provenance is retained separately; these are input fixtures,
never observations of a candidate migration.
"""
from __future__ import annotations
import base64
import hashlib
from typing import Any

SCHEMA = 'CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);\nCREATE TABLE blobs(blob_id TEXT PRIMARY KEY,content BLOB NOT NULL);\nCREATE TABLE documents(document_id TEXT PRIMARY KEY,source_id TEXT UNIQUE NOT NULL,source TEXT UNIQUE NOT NULL,blob_id TEXT NOT NULL,title TEXT NOT NULL);\nCREATE TABLE jobs(job_id TEXT PRIMARY KEY,epoch INTEGER NOT NULL,state TEXT NOT NULL,total INTEGER NOT NULL,completed INTEGER NOT NULL,error TEXT,manifest TEXT NOT NULL,content_hashes TEXT NOT NULL,receipt TEXT);'
AUTHOR_SQLITE_VERSION = '3.53.3'
SEEDS: dict[str, dict[str, Any]] = {'high': {'epoch': 9007199254740993, 'sha256': '06c77730b21f2e77554088f4429701013edd8dd2804ccc0a1a22ec57e549b8f2', 'bytes': 45056, 'base64': ''}, 'maximum': {'epoch': 9223372036854775807, 'sha256': '4dd58c3dcd12cdd9c63a1bdb8708c8bd162a9b707de7c851a383c4affeed47c5', 'bytes': 45056, 'base64': ''}}

def seed(name: str) -> bytes:
    row = SEEDS[name]
    raw = base64.b64decode(row['base64'], validate=True)
    if len(raw) != row['bytes'] or hashlib.sha256(raw).hexdigest() != row['sha256']:
        raise ValueError('Frozen counter input bytes differ')
    return raw


def inventory(name: str) -> dict[str, Any]:
    row = SEEDS[name]
    return {'schema': '0', 'tables': ['blobs', 'documents', 'jobs', 'metadata'],
            'blobs': [], 'documents': [], 'metadata': [['schema', '0']],
            'jobs': [['browser_counter', row['epoch'], 'queued', 0, 0, None, '[]', '[]', None]],
            'input_sha256': row['sha256'], 'input_bytes': row['bytes'],
            'candidate_code_executed': False}
